import{_ as t,o,c as a,a3 as n}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"Discussion of an Automatic Support Bot","description":"","frontmatter":{"translationSource":{"title":"关于自动售后bot的讨论","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=InpQXbNihnKGIZqs72DI6p","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/automatic-support-bot-discussion"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/automatic-support-bot-discussion"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/automatic-support-bot-discussion"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/automatic-support-bot-discussion"}]]},"headers":[],"relativePath":"automatic-support-bot-discussion.md","filePath":"logistics/src/page-InpQXbNihnKGIZqs72DI6p.md"}'),s={name:"automatic-support-bot-discussion.md"};function i(r,e,p,d,l,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<div class="logistics-content"><h1 id="discussion-of-an-automatic-support-bot" tabindex="-1">Discussion of an Automatic Support Bot <a class="header-anchor" href="#discussion-of-an-automatic-support-bot" aria-label="Permalink to &quot;Discussion of an Automatic Support Bot&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-23. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>InpQXbNihnKGIZqs72DI6p</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=InpQXbNihnKGIZqs72DI6p" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Use n8n for the workflow and maybe use snowluma for integration? We still need to detect when helpers come online, answer questions automatically, maintain a helper allowlist, and let helpers force a session to end. #jmy I&#39;ll work on it over the next few days.</p><p>The bot also needs something like intelligent mass cleanup when membership reaches 500 ().</p><p>And automatic group-announcement reminders at 475 members. Basically it is all node workflows in n8n now; waiting for jmy to deploy it.</p><p>＃东: This bot is certainly a good idea, but please don&#39;t let anything go wrong.</p><p>#凯 to 东: The bot breaking is quite possible. Some of the other functions above do not rely on AI and give reproducible, deterministic results (especially mass cleanup), so we decided to implement those in code.</p><p><span class="mark-grey">#jnk: snowluma broke first, I can&#39;t (</span></p><p><span class="mark-grey">#东: Does the bot need priority diagnostics too? No way.</span></p></div>',1)])])}const m=t(s,[["render",i]]);export{h as __pageData,m as default};
